// The committed corpus, generated by packages/protocol-vectors (protocol/vectors/frames.json).
type framesVectors struct {
	Version int `json:"version"`
	Cases   []struct {
		Name    string `json:"name"`
		Op      uint64 `json:"op"`
		N       uint64 `json:"n"`
		GroupID string `json:"group_id"` // 32 hex, or "" for null
		Payload string `json:"payload"`  // hex of the payload array alone
		Frame   string `json:"frame"`    // hex of the whole four-element frame
	} `json:"cases"`
	Rejects []struct {
		Name  string `json:"name"`
		Frame string `json:"frame"`
		Code  string `json:"code"`
	} `json:"rejects"`
}

func loadFrameVectors(t *testing.T) framesVectors {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "protocol", "vectors", "frames.json"))
	if err != nil {
		t.Fatalf("frames.json: %v", err)
	}
	var v framesVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("frames.json: %v", err)
	}
	if len(v.Cases) == 0 || len(v.Rejects) == 0 {
		t.Fatal("frames.json carries no cases or no rejects")
	}
	return v
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("hex %q: %v", s, err)
	}
	return b
}

// decodeServerFrameForTest reads element 0 and element 1 of any frame, in either direction.
// Decode itself refuses server opcodes from a client, which is what the read path wants; these
// tests need to look at what the encoder produced.
func decodeServerFrameForTest(b []byte) (Inbound, error) {
	var elems []cbor.RawMessage
	if err := cborx.Unmarshal(b, &elems); err != nil {
		return Inbound{}, err
	}
	if len(elems) != 4 {
		return Inbound{}, errors.New("frame is not four elements")
	}
	op, err := rawUint(elems[0])
	if err != nil {
		return Inbound{}, err
	}
	n, err := rawUint(elems[1])
	if err != nil {
		return Inbound{}, err
	}
	return Inbound{Op: Op(op), CID: n}, nil
}

// Every accept case encodes to exactly the committed bytes: one encoder, three languages.
func TestEveryOpcodeEncodesToTheCommittedFrame(t *testing.T) {
	v := loadFrameVectors(t)
	for _, c := range v.Cases {
		t.Run(c.Name, func(t *testing.T) {
			var gid *id.ID
			if c.GroupID != "" {
				parsed, err := id.Parse(c.GroupID)
				if err != nil {
					t.Fatalf("group_id: %v", err)
				}
				gid = &parsed
			}
			// Encode forces n = 0 for a frame whose Replay is false, so the corpus's non-zero
			// n cases must be built with Replay set: identify, resume, ready, resumed,
			// heartbeat, subscribe, unsubscribe, all six DS frames, message.plain and
			// interaction all carry n != 0.
			got, err := Encode(Frame{
				Op:      Op(c.Op),
				GroupID: gid,
				Payload: cbor.RawMessage(mustHex(t, c.Payload)),
				Replay:  c.N != 0,
			}, c.N)
			if err != nil {
				t.Fatalf("Encode: %v", err)
			}
			if want := mustHex(t, c.Frame); hex.EncodeToString(got) != hex.EncodeToString(want) {
				t.Fatalf("frame\n got %x\nwant %x", got, want)
			}
		})
	}
}

// The other half of the same rule: a frame the producer did not mark replayable is stamped n = 0
// whatever n is passed, so an ephemeral frame can never consume a replay sequence.
func TestANonReplayableFrameIsAlwaysStampedZero(t *testing.T) {
	p, err := PresencePayload(id.New(), 1, 1758659000, "")
	if err != nil {
		t.Fatalf("payload: %v", err)
	}
	b, err := Encode(Frame{Op: OpPresence, Payload: p}, 99)
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	in, err := decodeServerFrameForTest(b)
	if err != nil {
		t.Fatalf("decode: %v", err)
	}
	if in.CID != 0 {
		t.Fatalf("n = %d for a Replay:false frame, want 0", in.CID)
	}
}

// opSpec.replayable is the catalogue's own record of which server frames consume a replay
// sequence, and the committed corpus is the other statement of the same fact. They must agree, or
// one of the two is wrong and a client's resume replays the wrong set.
func TestTheCatalogueAndTheCorpusAgreeOnWhichServerFramesAreReplayable(t *testing.T) {
	v := loadFrameVectors(t)
	for _, c := range v.Cases {
		op := Op(c.Op)
		spec := opSpecs[op]
		if spec.fromClient {
			continue // n is the client's correlation id, not a replay sequence
		}
		if want := spec.replayable; (c.N != 0) != want {
			t.Errorf("%s: corpus n = %d but opSpecs[%d].replayable = %v", c.Name, c.N, op, want)
		}
	}
}

// The same rule for the payload's shape. `Decode` only ever checks `spec.elements` on a CLIENT
// frame, so nothing else in this package notices when a server frame's catalogue entry and the
// committed corpus drift apart — and the corpus is what a second implementation is written
// against. `resumed` gaining its third element (the rotated resume_token) is exactly the change
// that would have slipped through in one language only.
func TestTheCatalogueAndTheCorpusAgreeOnEveryPayloadElementCount(t *testing.T) {
	v := loadFrameVectors(t)
	for _, c := range v.Cases {
		t.Run(c.Name, func(t *testing.T) {
			var elems []cbor.RawMessage
			if err := cborx.Unmarshal(mustHex(t, c.Payload), &elems); err != nil {
				t.Fatalf("payload: %v", err)
			}
			want := opSpecs[Op(c.Op)].elements
			if len(elems) != want {
				t.Fatalf("corpus payload has %d elements but opSpecs[%d].elements = %d",
					len(elems), c.Op, want)
			}
		})
	}
}

// Every client-to-server case decodes back to the same opcode, correlation id and group.
func TestClientFramesDecodeBackToTheirFields(t *testing.T) {
	v := loadFrameVectors(t)
	for _, c := range v.Cases {
		if !isClientOp(Op(c.Op)) {
			continue
		}
		t.Run(c.Name, func(t *testing.T) {
			in, err := Decode(mustHex(t, c.Frame), 16384)
			if err != nil {
				t.Fatalf("Decode: %v", err)
			}
			if in.Op != Op(c.Op) {
				t.Errorf("Op = %d, want %d", in.Op, c.Op)
			}
			if in.CID != c.N {
				t.Errorf("CID = %d, want %d", in.CID, c.N)
			}
			if (in.GroupID == nil) != (c.GroupID == "") {
				t.Errorf("GroupID = %v, want %q", in.GroupID, c.GroupID)
			}
		})
	}
}

// The reject corpus: each entry names the E_FRAME_* code the decoder must produce.
func TestTheRejectCorpusIsRefusedWithTheNamedCode(t *testing.T) {
	v := loadFrameVectors(t)
	for _, r := range v.Rejects {
		t.Run(r.Name, func(t *testing.T) {
			_, err := Decode(mustHex(t, r.Frame), 16384)
			if err == nil {
				t.Fatalf("%s was accepted", r.Name)
			}
			var fe *FrameError
			if !errors.As(err, &fe) {
				t.Fatalf("got %v, want a *FrameError", err)
			}
			if fe.Code != r.Code {
				t.Fatalf("code = %s, want %s", fe.Code, r.Code)
			}
		})
	}
}

func TestAFrameOverTheReadLimitIsEFrameLimit(t *testing.T) {
	payload, err := cborx.Marshal([]any{make([]byte, 64)})
	if err != nil {
		t.Fatalf("payload: %v", err)
	}
	frame, err := Encode(Frame{Op: OpSubscribe, Payload: payload}, 1)
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	var fe *FrameError
	if _, err := Decode(frame, len(frame)-1); !errors.As(err, &fe) || fe.Code != "E_FRAME_LIMIT" {
		t.Fatalf("got %v, want E_FRAME_LIMIT", err)
	}
	if _, err := Decode(frame, len(frame)); err != nil {
		t.Fatalf("a frame of exactly the limit must be accepted: %v", err)
	}
}

func TestAnUnknownOpcodeIsAHardError(t *testing.T) {
	payload, err := cborx.Marshal([]any{})
	if err != nil {
		t.Fatalf("payload: %v", err)
	}
	frame, err := Encode(Frame{Op: Op(63), Payload: payload}, 1)
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	var fe *FrameError
	if _, err := Decode(frame, 16384); !errors.As(err, &fe) || fe.Code != "E_FRAME_TYPE" {
		t.Fatalf("got %v, want E_FRAME_TYPE — an unknown opcode is never ignored", err)
	}
	if fe.Close != CloseDecode {
		t.Fatalf("close code = %d, want 4002", fe.Close)
	}
}

// An opcode is a uint8 on this side. 256+6 must not wrap to 6 and be served as a heartbeat: it is
// an unknown opcode, exactly like 63.
func TestAnOpcodeThatOverflowsAByteIsAnUnknownOpcode(t *testing.T) {
	payload, err := cborx.Marshal([]any{uint64(1), uint64(2)})
	if err != nil {
		t.Fatalf("payload: %v", err)
	}
	frame, err := cborx.MarshalFrame(uint64(OpHeartbeat)+256, 1, nil, payload)
	if err != nil {
		t.Fatalf("MarshalFrame: %v", err)
	}
	var fe *FrameError
	if _, err := Decode(frame, 16384); !errors.As(err, &fe) || fe.Code != "E_FRAME_TYPE" {
		t.Fatalf("got %v, want E_FRAME_TYPE — opcode 262 is not heartbeat (6)", err)
	}
}

// Op 53 `call_ring` is server-to-client (L-GW-33): a client that sends one, of any shape, is
// refused at the opcode check with E_FRAME_TYPE. Attacker: a client forging a ring frame toward
// the instance in the hope it is relayed or acted on; the instance alone produces rings.
func TestOp53FromAClientIsEFrameType(t *testing.T) {
	call, channel, user := id.New(), id.New(), id.New()
	for _, payload := range [][]any{
		{call[:], channel[:], user[:], uint64(1), uint64(1758659030)},
		{call[:], channel[:], user[:], uint64(3), uint64(1758659030)},
		{call[:], channel[:], user[:], uint64(1)},
	} {
		raw, err := cborx.Marshal(payload)
		if err != nil {
			t.Fatalf("payload: %v", err)
		}
		frame, err := cborx.MarshalFrame(53, 0, nil, raw)
		if err != nil {
			t.Fatalf("MarshalFrame: %v", err)
		}
		var fe *FrameError
		if _, err := Decode(frame, 16384); !errors.As(err, &fe) || fe.Code != "E_FRAME_TYPE" {
			t.Fatalf("got %v, want E_FRAME_TYPE for a client op 53 with %d elements", err, len(payload))
		}
	}
}

// The server side of op 53: the catalogue knows it as a five-element, ungrouped, non-replayable
// S->C frame, and an encoded ring round-trips with n = 0 whatever n is passed.
func TestCallRingEncodesFiveElementsAndRoundTrips(t *testing.T) {
	spec, ok := opSpecs[OpCallRing]
	if !ok || OpCallRing != 53 {
		t.Fatalf("OpCallRing = %d, in catalogue %v; want 53 in the catalogue", OpCallRing, ok)
	}
	if spec.elements != 5 || spec.fromClient || spec.grouped || spec.replayable {
		t.Fatalf("opSpecs[53] = %+v, want {elements: 5} only", spec)
	}
	call, channel, user := id.New(), id.New(), id.New()
	raw, err := cborx.Marshal([]any{call[:], channel[:], user[:], uint64(2), uint64(1758659030)})
	if err != nil {
		t.Fatalf("payload: %v", err)
	}
	b, err := Encode(Frame{Op: OpCallRing, Payload: raw}, 7)
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	var elems []cbor.RawMessage
	if err := cborx.Unmarshal(b, &elems); err != nil || len(elems) != 4 {
		t.Fatalf("frame: %v, %d elements", err, len(elems))
	}
	if op, _ := rawUint(elems[0]); op != 53 {
		t.Fatalf("op = %d, want 53", op)
	}
	if n, _ := rawUint(elems[1]); n != 0 {
		t.Fatalf("n = %d, want 0 for an ephemeral frame", n)
	}
	if !isNull(elems[2]) {
		t.Fatalf("group_id = %x, want null", elems[2])
	}
	var payload []cbor.RawMessage
	if err := cborx.Unmarshal(elems[3], &payload); err != nil || len(payload) != 5 {
		t.Fatalf("payload: %v, %d elements, want 5", err, len(payload))
	}
	var gotCall id.ID
	if err := cborx.Unmarshal(payload[0], &gotCall); err != nil || gotCall != call {
		t.Fatalf("call_id = %v (%v), want %v", gotCall, err, call)
	}
	if state, _ := rawUint(payload[3]); state != 2 {
		t.Fatalf("state = %d, want 2", state)
	}
	if exp, _ := rawUint(payload[4]); exp != 1758659030 {
		t.Fatalf("expires_ts = %d, want 1758659030", exp)
	}
}

// Op 54 `community_changed` is server-to-client (dilla-web-3.1): a client that sends one is refused
// at the opcode check with E_FRAME_TYPE. Attacker: a client forging the notice toward the instance
// in the hope it is fanned out to the community's members; the instance alone produces it.
func TestOp54FromAClientIsEFrameType(t *testing.T) {
	cid := id.New()
	for _, payload := range [][]any{{cid[:]}, {cid[:], uint64(1)}} {
		raw, err := cborx.Marshal(payload)
		if err != nil {
			t.Fatalf("payload: %v", err)
		}
		frame, err := cborx.MarshalFrame(54, 0, nil, raw)
		if err != nil {
			t.Fatalf("MarshalFrame: %v", err)
		}
		var fe *FrameError
		if _, err := Decode(frame, 16384); !errors.As(err, &fe) || fe.Code != "E_FRAME_TYPE" {
			t.Fatalf("got %v, want E_FRAME_TYPE for a client op 54 with %d elements", err, len(payload))
		}
	}
}

// The server side of op 54: one element, ungrouped, non-replayable, and the encoded notice
// round-trips with n = 0 and the community id.
func TestCommunityChangedEncodesOneElementAndRoundTrips(t *testing.T) {
	spec, ok := opSpecs[OpCommunityChanged]
	if !ok || OpCommunityChanged != 54 {
		t.Fatalf("OpCommunityChanged = %d, in catalogue %v; want 54 in the catalogue", OpCommunityChanged, ok)
	}
	if spec.elements != 1 || spec.fromClient || spec.grouped || spec.replayable {
		t.Fatalf("opSpecs[54] = %+v, want {elements: 1} only", spec)
	}
	cid := id.New()
	raw, err := CommunityChangedPayload(cid)
	if err != nil {
		t.Fatalf("payload: %v", err)
	}
	b, err := Encode(Frame{Op: OpCommunityChanged, Payload: raw}, 7)
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	var elems []cbor.RawMessage
	if err := cborx.Unmarshal(b, &elems); err != nil || len(elems) != 4 {
		t.Fatalf("frame: %v, %d elements", err, len(elems))
	}
	if op, _ := rawUint(elems[0]); op != 54 {
		t.Fatalf("op = %d, want 54", op)
	}
	if n, _ := rawUint(elems[1]); n != 0 {
		t.Fatalf("n = %d, want 0 for an ephemeral frame", n)
	}
	var payload []cbor.RawMessage
	if err := cborx.Unmarshal(elems[3], &payload); err != nil || len(payload) != 1 {
		t.Fatalf("payload: %v, %d elements, want 1", err, len(payload))
	}
	var got id.ID
	if err := cborx.Unmarshal(payload[0], &got); err != nil || got != cid {
		t.Fatalf("community_id = %v (%v), want %v", got, err, cid)
	}
}

// The upload class (web3.7 SB1, R29): message.ct carries it as its 7th element, a uint for a class
// upload and null for a legacy one.
func TestMessageCTCarriesTheUploadClass(t *testing.T) {
	if got := opSpecs[OpMessageCT].elements; got != 7 {
		t.Fatalf("opSpecs[OpMessageCT].elements = %d, want 7", got)
	}
	zero := uint8(0)
	for _, c := range []struct {
		name  string
		class *uint8
		want  string
	}{{"class 0", &zero, "00"}, {"legacy", nil, "f6"}} {
		raw, err := MessageCTPayload(1, 2, id.New(), []byte("ct"), make([]byte, 32), 3, c.class)
		if err != nil {
			t.Fatalf("%s: MessageCTPayload: %v", c.name, err)
		}
		var elems []cbor.RawMessage
		if err := cborx.Unmarshal(raw, &elems); err != nil {
			t.Fatalf("%s: decode: %v", c.name, err)
		}
		if len(elems) != 7 {
			t.Fatalf("%s: %d elements, want 7", c.name, len(elems))
		}
		if got := hex.EncodeToString(elems[6]); got != c.want {
			t.Fatalf("%s: the 7th element is %s, want %s", c.name, got, c.want)
		}
	}
}

// Op 55 `afk_away` is server-to-client (AW3): a client that sends one, of any shape, is refused at
// the opcode check with E_FRAME_TYPE. Attacker: a client forging an away notice toward the
// instance in the hope it is fanned out to the community; the instance alone produces it.
func TestOp55FromAClientIsEFrameType(t *testing.T) {
	cid, uid := id.New(), id.New()
	for _, payload := range [][]any{{cid[:], uid[:], uint64(1758659000)}, {cid[:], uid[:], uint64(1758659000), uint64(1)}} {
		raw, err := cborx.Marshal(payload)
		if err != nil {
			t.Fatalf("payload: %v", err)
		}
		frame, err := cborx.MarshalFrame(55, 0, nil, raw)
		if err != nil {
			t.Fatalf("MarshalFrame: %v", err)
		}
		var fe *FrameError
		if _, err := Decode(frame, 16384); !errors.As(err, &fe) || fe.Code != "E_FRAME_TYPE" {
			t.Fatalf("got %v, want E_FRAME_TYPE for a client op 55 with %d elements", err, len(payload))
		}
	}
}

// The server side of op 55: three elements, ungrouped, non-replayable (n = 0), and the encoded
// notice round-trips with the community id, the user id and since_ts (0 means cleared).
func TestAFKAwayEncodesThreeElementsAndRoundTrips(t *testing.T) {
	spec, ok := opSpecs[OpAFKAway]
	if !ok || OpAFKAway != 55 {
		t.Fatalf("OpAFKAway = %d, in catalogue %v; want 55 in the catalogue", OpAFKAway, ok)
	}
	if spec.elements != 3 || spec.fromClient || spec.grouped || spec.replayable {
		t.Fatalf("opSpecs[55] = %+v, want {elements: 3} only", spec)
	}
	if opNames[OpAFKAway] != "afk_away" {
		t.Fatalf("opNames[55] = %q, want afk_away", opNames[OpAFKAway])
	}
	for _, since := range []uint64{1758659000, 0} {
		cid, uid := id.New(), id.New()
		raw, err := AFKAwayPayload(cid, uid, since)
		if err != nil {
			t.Fatalf("payload: %v", err)
		}
		b, err := Encode(Frame{Op: OpAFKAway, Payload: raw}, 7)
		if err != nil {
			t.Fatalf("Encode: %v", err)
		}
		var elems []cbor.RawMessage
		if err := cborx.Unmarshal(b, &elems); err != nil || len(elems) != 4 {
			t.Fatalf("frame: %v, %d elements", err, len(elems))
		}
		if op, _ := rawUint(elems[0]); op != 55 {
			t.Fatalf("op = %d, want 55", op)
		}
		if n, _ := rawUint(elems[1]); n != 0 {
			t.Fatalf("n = %d, want 0 for an ephemeral frame", n)
		}
		if !isNull(elems[2]) {
			t.Fatalf("group_id = %x, want null", elems[2])
		}
		var payload []cbor.RawMessage
		if err := cborx.Unmarshal(elems[3], &payload); err != nil || len(payload) != 3 {
			t.Fatalf("payload: %v, %d elements, want 3", err, len(payload))
		}
		var gotC, gotU id.ID
		if err := cborx.Unmarshal(payload[0], &gotC); err != nil || gotC != cid {
			t.Fatalf("community_id = %v (%v), want %v", gotC, err, cid)
		}
		if err := cborx.Unmarshal(payload[1], &gotU); err != nil || gotU != uid {
			t.Fatalf("user_id = %v (%v), want %v", gotU, err, uid)
		}
		if got, err := rawUint(payload[2]); err != nil || got != since {
			t.Fatalf("since_ts = %d (%v), want %d", got, err, since)
		}
	}
}
